export interface ConnectorConfig {
  githubToken: string;
  githubOwner: string;
  githubRepo: string;
  fetch?: typeof fetch;
}

export interface ZendeskTicketCreatedPayload {
  account_id: number;
  detail: {
    actor_id: string;
    assignee_id: string;
    brand_id: string;
    created_at: string;
    custom_status: string;
    description: string | null;
    external_id: string | null;
    form_id: string;
    id: string;
    is_public: boolean;
    organization_id: string;
    priority: string;
    requester_id: string;
    status: string;
    subject: string;
    submitter_id: string;
    tags: string[];
    type: string | null;
    updated_at: string;
    via: {
      channel: string;
    };
  };
  event: {
    current: string;
    meta: {
      sequence: {
        id: number;
        position: number;
      };
    };
    previous: string | null;
  };
  id: string;
  subject: string;
  time: string;
  type: string;
  zendesk_event_version: string;
}

export interface HandleResult {
  zendeskTicketId: string;
  githubIssueNumber: number;
  githubIssueUrl: string;
  githubHtmlUrl: string;
}

export async function handle(
  payload: ZendeskTicketCreatedPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch;

  if (payload.type !== 'zen:event-type:ticket.created') {
    throw new Error(`Invalid webhook type: expected 'zen:event-type:ticket.created', got '${payload.type}'`);
  }

  const ticketId = payload.detail?.id;
  const subject = payload.detail?.subject;
  const description = payload.detail?.description;

  if (!ticketId) {
    throw new Error('Missing required field: detail.id (Zendesk ticket ID)');
  }
  if (!subject) {
    throw new Error('Missing required field: detail.subject (Zendesk ticket subject)');
  }
  if (description === undefined || description === null) {
    throw new Error('Missing required field: detail.description (Zendesk ticket description)');
  }

  const url = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues`;
  const body = JSON.stringify({
    title: subject,
    body: description,
  });

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.githubToken}`,
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json',
      'User-Agent': 'patchbay-connector',
    },
    body,
  });

  if (!response.ok) {
    throw new Error(`GitHub API error: ${response.status} ${response.statusText} for POST ${url}`);
  }

  const issue = await response.json() as {
    number: number;
    url: string;
    html_url: string;
  };

  return {
    zendeskTicketId: ticketId,
    githubIssueNumber: issue.number,
    githubIssueUrl: issue.url,
    githubHtmlUrl: issue.html_url,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, ZendeskTicketCreatedPayload } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      githubToken: 'test-token',
      githubOwner: 'octocat',
      githubRepo: 'Hello-World',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.zendeskTicketId).toBe('14038');
    expect(result.githubIssueNumber).toBe(1347);
    expect(result.githubHtmlUrl).toBe('https://github.com/octocat/Hello-World/issues/1347');
  });
});

describe('handle', () => {
  it('creates a GitHub issue with correct field mapping', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.github.com/repos/test-owner/test-repo/issues' && req.method === 'POST') {
        return jsonResponse({
          number: 42,
          url: 'https://api.github.com/repos/test-owner/test-repo/issues/42',
          html_url: 'https://github.com/test-owner/test-repo/issues/42',
        }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: ZendeskTicketCreatedPayload = {
      ...SOURCE_EXAMPLE,
      detail: {
        ...SOURCE_EXAMPLE.detail,
        id: '999',
        subject: 'Test Issue Title',
        description: 'Test issue description body',
      },
    };

    const config: ConnectorConfig = {
      githubToken: 'ghp_test123',
      githubOwner: 'test-owner',
      githubRepo: 'test-repo',
      fetch,
    };

    const result = await handle(payload, config);

    expect(calls).toHaveLength(1);
    expect(calls[0].method).toBe('POST');
    expect(calls[0].url).toBe('https://api.github.com/repos/test-owner/test-repo/issues');
    expect(calls[0].headers.get('authorization')).toBe('Bearer ghp_test123');
    expect(calls[0].headers.get('accept')).toBe('application/vnd.github+json');
    expect(calls[0].json).toEqual({
      title: 'Test Issue Title',
      body: 'Test issue description body',
    });
    expect(result).toEqual({
      zendeskTicketId: '999',
      githubIssueNumber: 42,
      githubIssueUrl: 'https://api.github.com/repos/test-owner/test-repo/issues/42',
      githubHtmlUrl: 'https://github.com/test-owner/test-repo/issues/42',
    });
  });

  it('throws on missing detail.id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201));
    const payload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, id: undefined as unknown as string },
    };

    await expect(handle(payload as unknown as ZendeskTicketCreatedPayload, {
      githubToken: 't',
      githubOwner: 'o',
      githubRepo: 'r',
      fetch,
    })).rejects.toThrow('Missing required field: detail.id');
  });

  it('throws on missing detail.subject', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201));
    const payload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, subject: undefined as unknown as string },
    };

    await expect(handle(payload as unknown as ZendeskTicketCreatedPayload, {
      githubToken: 't',
      githubOwner: 'o',
      githubRepo: 'r',
      fetch,
    })).rejects.toThrow('Missing required field: detail.subject');
  });

  it('throws on missing detail.description', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201));
    const payload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, description: null },
    };

    await expect(handle(payload as unknown as ZendeskTicketCreatedPayload, {
      githubToken: 't',
      githubOwner: 'o',
      githubRepo: 'r',
      fetch,
    })).rejects.toThrow('Missing required field: detail.description');
  });

  it('throws on invalid webhook type', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201));
    const payload = {
      ...SOURCE_EXAMPLE,
      type: 'zen:event-type:ticket.updated',
    };

    await expect(handle(payload as unknown as ZendeskTicketCreatedPayload, {
      githubToken: 't',
      githubOwner: 'o',
      githubRepo: 'r',
      fetch,
    })).rejects.toThrow("Invalid webhook type: expected 'zen:event-type:ticket.created', got 'zen:event-type:ticket.updated'");
  });

  it('throws on non-2xx GitHub response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ message: 'Validation Failed' }, 422));

    const payload: ZendeskTicketCreatedPayload = {
      ...SOURCE_EXAMPLE,
      detail: {
        ...SOURCE_EXAMPLE.detail,
        id: '123',
        subject: 'Test',
        description: 'Body',
      },
    };

    await expect(handle(payload, {
      githubToken: 't',
      githubOwner: 'o',
      githubRepo: 'r',
      fetch,
    })).rejects.toThrow('GitHub API error: 422 Unprocessable Entity for POST https://api.github.com/repos/o/r/issues');

    expect(calls).toHaveLength(1);
  });

  it('uses injected fetch from config', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({
      number: 1,
      url: 'https://api.github.com/repos/o/r/issues/1',
      html_url: 'https://github.com/o/r/issues/1',
    }, 201));

    await handle({
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, id: '1', subject: 'S', description: 'D' },
    }, {
      githubToken: 'token',
      githubOwner: 'o',
      githubRepo: 'r',
      fetch,
    });

    expect(calls).toHaveLength(1);
  });
});

